<template><section class="report-page"><header class="page-header"><div><h2>App 测试报告</h2><p v-if="run">{{run.case_name}} · {{run.application_name}} · {{run.device_name}} · 执行人：{{run.created_by_name||'-'}}</p></div><n-space><n-button @click="load">刷新</n-button><n-button v-if="run&&active(run.status)" type="error" secondary @click="stop">停止任务</n-button></n-space></header><n-spin :show="loading"><template v-if="run"><div class="context"><div><span>执行编号</span><strong>{{run.execution_no}}</strong></div><div><span>状态</span><n-tag :type="labels[run.status]?.[1]||'default'">{{labels[run.status]?.[0]||run.status}}</n-tag></div><div><span>进度</span><n-progress type="line" :percentage="run.progress" :height="7"/></div><div><span>应用版本</span><strong>{{run.version_name||'设备已安装版本'}}</strong></div><div><span>开始时间</span><strong>{{date(run.started_at)}}</strong></div><div><span>结束时间</span><strong>{{date(run.finished_at)}}</strong></div></div><n-alert v-if="run.error_message" type="error" class="error">{{run.error_message}}</n-alert><div class="metrics"><article><span>总步骤</span><strong>{{run.summary?.total||run.step_results.length}}</strong></article><article><span>成功</span><strong class="success">{{run.summary?.passed||0}}</strong></article><article><span>失败</span><strong class="failed">{{run.summary?.failed||0}}</strong></article><article><span>跳过</span><strong>{{run.summary?.skipped||0}}</strong></article></div><section class="panel"><header><strong>步骤明细</strong><span>失败步骤自动保存截图和页面结构</span></header><n-data-table :columns="columns" :data="run.step_results" :row-key="r=>r.id"/></section><section class="panel"><header><strong>实时执行日志</strong><span>任务运行期间每 3 秒更新</span></header><pre>{{log||'暂无日志'}}</pre></section></template></n-spin></section></template>
<script setup lang="ts">
import { usePolling } from '@/hooks/web/usePolling';
import { appStatusLabels as labels, isAppActive as active } from '@/utils/executionStatus';
import{h,onMounted,ref}from'vue';import{NButton,NSpace,NTag,useMessage}from'naive-ui';import{useRoute}from'vue-router';import{AppTestAPI,type AppRun}from'@/api/case_app/http';const route=useRoute(),message=useMessage(),run=ref<AppRun>(),log=ref(''),loading=ref(false);const poller = usePolling();const date=(v?:string)=>v?new Date(v).toLocaleString():'-';const columns:any[]=[{title:'#',key:'order',width:60},{title:'步骤',key:'name'},{title:'状态',key:'status',width:90,render:(r:any)=>h(NTag,{type:r.status==='passed'?'success':r.status==='failed'?'error':r.status==='running'?'info':'default'},{default:()=>({passed:'通过',failed:'失败',running:'执行中',skipped:'跳过'}as any)[r.status]||r.status})},{title:'耗时',key:'duration_ms',width:100,render:(r:any)=>`${r.duration_ms} ms`},{title:'结果',key:'message',ellipsis:{tooltip:true}},{title:'附件',key:'artifacts',width:150,render:(r:any)=>h(NSpace,{size:10,wrap:true},{default:()=>r.artifacts.map((a:any)=>h(NButton,{text:true,type:'primary',onClick:()=>openArtifact(a.id,a.artifact_type)},{default:()=>a.artifact_type==='screenshot'?'截图':'页面结构'}))})}];async function openArtifact(id:number,type:string){if(!run.value)return;try{const blob=await AppTestAPI.artifact(run.value.id,id);const url=URL.createObjectURL(blob);window.open(url,'_blank');window.setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e:any){message.error(e?.message||`${type}加载失败`);}}async function load(){loading.value=!run.value;try{run.value=await AppTestAPI.run(Number(route.params.id));log.value=(await AppTestAPI.log(run.value.id)).content;if(!active(run.value.status))poller.stop();}catch(e:any){message.error(e?.message||'报告加载失败');}finally{loading.value=false;}}async function stop(){if(run.value){await AppTestAPI.stop(run.value.id);await load();}}onMounted(async()=>{await load();if(run.value&&active(run.value.status))poller.start(()=>void load(),3000)});</script>
<style scoped lang="less">.report-page{padding:24px 28px;background:#f5f7fb}.page-header{display:flex;justify-content:space-between;gap:16px}.page-header h2{margin:0}.page-header p{margin:8px 0 20px;color:#7b8ba3}.context,.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));overflow:hidden;border:1px solid #e2e8f0;border-radius:10px;background:#fff}.context>div,.metrics article{padding:15px 16px;border-right:1px solid #e2e8f0}.context span,.metrics span{display:block;color:#8290a5;font-size:12px}.context strong,.metrics strong{display:block;margin-top:6px;color:#243249;font-size:17px}.metrics{margin-top:16px}.metrics strong{font-size:25px}.metrics .success{color:#159b67}.metrics .failed{color:#dc2626}.error{margin-top:16px}.panel{margin-top:16px;padding:18px;border:1px solid #e2e8f0;border-radius:10px;background:#fff}.panel header{margin-bottom:14px}.panel header strong,.panel header span{display:block}.panel header span{margin-top:4px;color:#8290a5;font-size:12px}.panel pre{max-height:340px;overflow:auto;padding:14px;border-radius:8px;background:#172033;color:#d9e3f1;font:12px/1.65 monospace;white-space:pre-wrap}@media(max-width:640px){.report-page{padding:16px}.page-header{flex-direction:column}.context,.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
